    ['courses','fas fa-plus-circle','Add Course'],['courses','fas fa-layer-group','Open Course Content'],['users','fas fa-user-plus','Enroll Student'],['assignments','fas fa-tasks','Create Assignment'],['live-sessions','fas fa-video','Schedule Live Session'],['recovery-plan-templates','fas fa-route','Create Recovery Plan'],['settings','fas fa-cog','Site Settings'],
