    <section class="admin-dashboard-card admin-dashboard-content" aria-labelledby="content-title"><header class="admin-dashboard-section-heading"><div><p class="admin-dashboard-eyebrow">Content operations</p><h2 id="content-title">Publishing status</h2></div><a href="<?=$base?>/admin/courses">Manage content</a></header><dl><?php foreach($dashboard['content'] as $item): ?><div><dt><?=mmh_dashboard_escape($item['label'])?></dt><dd><a href="<?=$base?>/admin/<?=mmh_dashboard_escape($item['url'])?>"><?=mmh_dashboard_escape($item['count'])?></a></dd></div><?php endforeach;?></dl></section>
